residual_method_source:
function (object, type = if (isGLMM(object)) "deviance" else "response", 
    scaled = FALSE, ...) 
{
    r <- residuals(object@resp, type, ...)
    fr <- model.frame(object)
    if (is.null(nm <- rownames(fr))) 
        nm <- seq_along(r)
    names(r) <- nm
    if (scaled) 
        r <- r/sigma(object)
    if (!is.null(na.action <- attr(fr, "na.action"))) 
        naresid(na.action, r)
    else r
}
